// src/tokenizer.zig: 소스코드 → Token 스트림

const std = @import("std");

pub const Token = struct {
    tag: Tag,
    start: usize,
    end: usize,
    line: usize,
    column: usize,

    pub const Tag = enum {
        // Keywords
        fn_,
        const_,
        var_,
        if_,
        else_,
        while_,
        for_,
        return_,
        struct_,
        enum_,
        union_,
        error_,
        try_,
        catch_,
        pub_,
        inline_,
        comptime_,

        // Literals
        integer,
        float,
        string,
        char_literal,
        true_,
        false_,
        null_,

        // Identifiers & types
        identifier,

        // Operators
        plus,          // +
        minus,         // -
        star,          // *
        slash,         // /
        percent,       // %
        equal,         // =
        equal_equal,   // ==
        bang,          // !
        bang_equal,    // !=
        less,          // <
        less_equal,    // <=
        greater,       // >
        greater_equal, // >=
        ampersand,     // &
        pipe,          // |
        caret,         // ^
        tilde,         // ~
        lshift,        // <<
        rshift,        // >>
        and_,          // and
        or_,           // or
        not_,          // not
        dot,           // .
        arrow,         // =>
        question,      // ?
        colon,         // :
        double_colon,  // ::

        // Delimiters
        lparen,        // (
        rparen,        // )
        lbrace,        // {
        rbrace,        // }
        lbracket,      // [
        rbracket,      // ]
        semicolon,     // ;
        comma,         // ,

        // Special
        eof,
        invalid,
    };

    pub fn lexeme(self: Token, source: []const u8) []const u8 {
        return source[self.start..self.end];
    }
};

pub const Tokenizer = struct {
    source: []const u8,
    pos: usize,
    line: usize,
    column: usize,
    line_start: usize,

    pub fn init(source: []const u8) Tokenizer {
        return .{
            .source = source,
            .pos = 0,
            .line = 1,
            .column = 1,
            .line_start = 0,
        };
    }

    pub fn nextToken(self: *Tokenizer) Token {
        // Skip whitespace and comments
        while (self.pos < self.source.len) {
            const c = self.source[self.pos];

            if (isWhitespace(c)) {
                if (c == '\n') {
                    self.line += 1;
                    self.line_start = self.pos + 1;
                    self.column = 1;
                } else {
                    self.column += 1;
                }
                self.pos += 1;
                continue;
            }

            // Line comment
            if (c == '/' and self.peek() == '/') {
                while (self.pos < self.source.len and self.source[self.pos] != '\n') {
                    self.pos += 1;
                }
                continue;
            }

            // Block comment
            if (c == '/' and self.peek() == '*') {
                self.pos += 2;
                self.column += 2;
                while (self.pos < self.source.len - 1) {
                    if (self.source[self.pos] == '*' and self.source[self.pos + 1] == '/') {
                        self.pos += 2;
                        self.column += 2;
                        break;
                    }
                    if (self.source[self.pos] == '\n') {
                        self.line += 1;
                        self.line_start = self.pos + 1;
                        self.column = 1;
                    } else {
                        self.column += 1;
                    }
                    self.pos += 1;
                }
                continue;
            }

            break;
        }

        if (self.pos >= self.source.len) {
            return Token{
                .tag = .eof,
                .start = self.pos,
                .end = self.pos,
                .line = self.line,
                .column = self.column,
            };
        }

        const start = self.pos;
        const start_column = self.column;
        const c = self.source[self.pos];

        // Number literal
        if (isDigit(c)) {
            return self.scanNumber(start, start_column);
        }

        // String literal
        if (c == '"') {
            return self.scanString(start, start_column);
        }

        // Character literal
        if (c == '\'') {
            return self.scanCharLiteral(start, start_column);
        }

        // Identifier or keyword
        if (isIdentifierStart(c)) {
            return self.scanIdentifier(start, start_column);
        }

        // Operators and delimiters
        return self.scanOperator(start, start_column);
    }

    fn scanNumber(self: *Tokenizer, start: usize, start_column: usize) Token {
        while (self.pos < self.source.len and isDigit(self.source[self.pos])) {
            self.pos += 1;
            self.column += 1;
        }

        // Float
        if (self.pos < self.source.len and self.source[self.pos] == '.') {
            self.pos += 1;
            self.column += 1;

            while (self.pos < self.source.len and isDigit(self.source[self.pos])) {
                self.pos += 1;
                self.column += 1;
            }

            return Token{
                .tag = .float,
                .start = start,
                .end = self.pos,
                .line = self.line,
                .column = start_column,
            };
        }

        return Token{
            .tag = .integer,
            .start = start,
            .end = self.pos,
            .line = self.line,
            .column = start_column,
        };
    }

    fn scanString(self: *Tokenizer, start: usize, start_column: usize) Token {
        self.pos += 1; // Skip opening "
        self.column += 1;

        while (self.pos < self.source.len and self.source[self.pos] != '"') {
            if (self.source[self.pos] == '\\') {
                self.pos += 2;
                self.column += 2;
            } else if (self.source[self.pos] == '\n') {
                self.line += 1;
                self.line_start = self.pos + 1;
                self.column = 1;
                self.pos += 1;
            } else {
                self.pos += 1;
                self.column += 1;
            }
        }

        if (self.pos < self.source.len) {
            self.pos += 1; // Skip closing "
            self.column += 1;
        }

        return Token{
            .tag = .string,
            .start = start,
            .end = self.pos,
            .line = self.line,
            .column = start_column,
        };
    }

    fn scanCharLiteral(self: *Tokenizer, start: usize, start_column: usize) Token {
        self.pos += 1;
        self.column += 1;

        if (self.source[self.pos] == '\\') {
            self.pos += 2;
            self.column += 2;
        } else {
            self.pos += 1;
            self.column += 1;
        }

        if (self.pos < self.source.len and self.source[self.pos] == '\'') {
            self.pos += 1;
            self.column += 1;
        }

        return Token{
            .tag = .char_literal,
            .start = start,
            .end = self.pos,
            .line = self.line,
            .column = start_column,
        };
    }

    fn scanIdentifier(self: *Tokenizer, start: usize, start_column: usize) Token {
        while (self.pos < self.source.len and isIdentifierContinue(self.source[self.pos])) {
