// 🦎 Mini Zig Compiler - Phase 2.1: Tokenizer
// src/tokenizer.zig: 소스코드 → Token 스트림

const std = @import("std");

pub const Token = struct {
    tag: Tag,
    start: usize,
    end: usize,
    line: usize,
    column: usize,

    pub const Tag = enum {
        // Keywords
        fn_,
        const_,
        var_,
        if_,
        else_,
        while_,
        for_,
        return_,
        struct_,
        enum_,
        union_,
        error_,
        try_,
        catch_,
        pub_,
        inline_,
        comptime_,

        // Literals
        integer,
        float,
        string,
        char_literal,
        true_,
        false_,
        null_,

        // Identifiers & types
        identifier,

        // Operators
        plus,          // +
        minus,         // -
        star,          // *
        slash,         // /
        percent,       // %
        equal,         // =
        equal_equal,   // ==
        bang,          // !
        bang_equal,    // !=
        less,          // <
        less_equal,    // <=
        greater,       // >
        greater_equal, // >=
        ampersand,     // &
        pipe,          // |
        caret,         // ^
        tilde,         // ~
        lshift,        // <<
        rshift,        // >>
        and_,          // and
        or_,           // or
        not_,          // not
        dot,           // .
        arrow,         // =>
        question,      // ?
        colon,         // :
        double_colon,  // ::

        // Delimiters
        lparen,        // (
        rparen,        // )
        lbrace,        // {
        rbrace,        // }
        lbracket,      // [
        rbracket,      // ]
        semicolon,     // ;
        comma,         // ,

        // Special
        eof,
        invalid,
    };

    pub fn lexeme(self: Token, source: []const u8) []const u8 {
        return source[self.start..self.end];
    }
};

pub const Tokenizer = struct {
    source: []const u8,
    pos: usize,
    line: usize,
    column: usize,
    line_start: usize,

    pub fn init(source: []const u8) Tokenizer {
        return .{
            .source = source,
            .pos = 0,
            .line = 1,
            .column = 1,
            .line_start = 0,
        };
    }

    pub fn nextToken(self: *Tokenizer) Token {
        // Skip whitespace and comments
        while (self.pos < self.source.len) {
            const c = self.source[self.pos];

            if (isWhitespace(c)) {
                if (c == '\n') {
                    self.line += 1;
                    self.line_start = self.pos + 1;
                    self.column = 1;
                } else {
                    self.column += 1;
                }
                self.pos += 1;
                continue;
            }

            // Line comment
            if (c == '/' and self.peek() == '/') {
                while (self.pos < self.source.len and self.source[self.pos] != '\n') {
                    self.pos += 1;
                }
                continue;
            }

            // Block comment
            if (c == '/' and self.peek() == '*') {
                self.pos += 2;
                self.column += 2;
                while (self.pos < self.source.len - 1) {
                    if (self.source[self.pos] == '*' and self.source[self.pos + 1] == '/') {
                        self.pos += 2;
                        self.column += 2;
                        break;
                    }
                    if (self.source[self.pos] == '\n') {
                        self.line += 1;
                        self.line_start = self.pos + 1;
                        self.column = 1;
                    } else {
                        self.column += 1;
                    }
                    self.pos += 1;
                }
                continue;
            }

            break;
        }

        if (self.pos >= self.source.len) {
            return Token{
                .tag = .eof,
                .start = self.pos,
                .end = self.pos,
                .line = self.line,
                .column = self.column,
            };
        }

        const start = self.pos;
        const start_column = self.column;
        const c = self.source[self.pos];

        // Number literal
        if (isDigit(c)) {
            return self.scanNumber(start, start_column);
        }

        // String literal
        if (c == '"') {
            return self.scanString(start, start_column);
        }

        // Character literal
        if (c == '\'') {
            return self.scanCharLiteral(start, start_column);
        }

        // Identifier or keyword
        if (isIdentifierStart(c)) {
            return self.scanIdentifier(start, start_column);
        }

        // Operators and delimiters
        return self.scanOperator(start, start_column);
    }

    fn scanNumber(self: *Tokenizer, start: usize, start_column: usize) Token {
        while (self.pos < self.source.len and isDigit(self.source[self.pos])) {
            self.pos += 1;
            self.column += 1;
        }

        // Float
        if (self.pos < self.source.len and self.source[self.pos] == '.') {
            self.pos += 1;
            self.column += 1;

            while (self.pos < self.source.len and isDigit(self.source[self.pos])) {
                self.pos += 1;
                self.column += 1;
            }

            return Token{
                .tag = .float,
                .start = start,
                .end = self.pos,
                .line = self.line,
                .column = start_column,
            };
        }

        return Token{
            .tag = .integer,
            .start = start,
            .end = self.pos,
            .line = self.line,
            .column = start_column,
        };
    }

    fn scanString(self: *Tokenizer, start: usize, start_column: usize) Token {
        self.pos += 1; // Skip opening "
        self.column += 1;

        while (self.pos < self.source.len and self.source[self.pos] != '"') {
            if (self.source[self.pos] == '\\') {
                self.pos += 2;
                self.column += 2;
            } else if (self.source[self.pos] == '\n') {
                self.line += 1;
                self.line_start = self.pos + 1;
                self.column = 1;
                self.pos += 1;
            } else {
                self.pos += 1;
                self.column += 1;
            }
        }

        if (self.pos < self.source.len) {
            self.pos += 1; // Skip closing "
            self.column += 1;
        }

        return Token{
            .tag = .string,
            .start = start,
            .end = self.pos,
            .line = self.line,
            .column = start_column,
        };
    }

    fn scanCharLiteral(self: *Tokenizer, start: usize, start_column: usize) Token {
        self.pos += 1;
        self.column += 1;

        if (self.source[self.pos] == '\\') {
            self.pos += 2;
            self.column += 2;
        } else {
            self.pos += 1;
            self.column += 1;
        }

        if (self.pos < self.source.len and self.source[self.pos] == '\'') {
            self.pos += 1;
            self.column += 1;
        }

        return Token{
            .tag = .char_literal,
            .start = start,
            .end = self.pos,
            .line = self.line,
            .column = start_column,
        };
    }

    fn scanIdentifier(self: *Tokenizer, start: usize, start_column: usize) Token {
        while (self.pos < self.source.len and isIdentifierContinue(self.source[self.pos])) {
            self.pos += 1;
            self.column += 1;
        }

        const text = self.source[start..self.pos];
        const tag = getKeywordTag(text) orelse .identifier;

        return Token{
            .tag = tag,
            .start = start,
            .end = self.pos,
            .line = self.line,
            .column = start_column,
        };
    }

    fn scanOperator(self: *Tokenizer, start: usize, start_column: usize) Token {
        const c = self.source[self.pos];
        self.pos += 1;
        self.column += 1;

        const tag: Token.Tag = switch (c) {
            '+' => .plus,
            '-' => {
                if (self.pos < self.source.len and self.source[self.pos] == '>') {
                    self.pos += 1;
                    self.column += 1;
                    return Token{ .tag = .arrow, .start = start, .end = self.pos, .line = self.line, .column = start_column };
                }
                return Token{ .tag = .minus, .start = start, .end = self.pos, .line = self.line, .column = start_column };
            },
            '*' => .star,
            '/' => .slash,
            '%' => .percent,
            '=' => {
                if (self.pos < self.source.len and self.source[self.pos] == '=') {
                    self.pos += 1;
                    self.column += 1;
                    return Token{ .tag = .equal_equal, .start = start, .end = self.pos, .line = self.line, .column = start_column };
                }
                return Token{ .tag = .equal, .start = start, .end = self.pos, .line = self.line, .column = start_column };
            },
            '!' => {
                if (self.pos < self.source.len and self.source[self.pos] == '=') {
                    self.pos += 1;
                    self.column += 1;
                    return Token{ .tag = .bang_equal, .start = start, .end = self.pos, .line = self.line, .column = start_column };
                }
                return Token{ .tag = .bang, .start = start, .end = self.pos, .line = self.line, .column = start_column };
            },
            '<' => {
                if (self.pos < self.source.len) {
                    if (self.source[self.pos] == '=') {
                        self.pos += 1;
                        self.column += 1;
                        return Token{ .tag = .less_equal, .start = start, .end = self.pos, .line = self.line, .column = start_column };
                    } else if (self.source[self.pos] == '<') {
                        self.pos += 1;
                        self.column += 1;
                        return Token{ .tag = .lshift, .start = start, .end = self.pos, .line = self.line, .column = start_column };
                    }
                }
                return Token{ .tag = .less, .start = start, .end = self.pos, .line = self.line, .column = start_column };
            },
            '>' => {
                if (self.pos < self.source.len) {
                    if (self.source[self.pos] == '=') {
                        self.pos += 1;
                        self.column += 1;
                        return Token{ .tag = .greater_equal, .start = start, .end = self.pos, .line = self.line, .column = start_column };
                    } else if (self.source[self.pos] == '>') {
                        self.pos += 1;
                        self.column += 1;
                        return Token{ .tag = .rshift, .start = start, .end = self.pos, .line = self.line, .column = start_column };
                    }
                }
                return Token{ .tag = .greater, .start = start, .end = self.pos, .line = self.line, .column = start_column };
            },
            '&' => .ampersand,
            '|' => .pipe,
            '^' => .caret,
            '~' => .tilde,
            '.' => .dot,
            '?' => .question,
            ':' => {
                if (self.pos < self.source.len and self.source[self.pos] == ':') {
                    self.pos += 1;
                    self.column += 1;
                    return Token{ .tag = .double_colon, .start = start, .end = self.pos, .line = self.line, .column = start_column };
                }
                return Token{ .tag = .colon, .start = start, .end = self.pos, .line = self.line, .column = start_column };
            },
            '(' => .lparen,
            ')' => .rparen,
            '{' => .lbrace,
            '}' => .rbrace,
            '[' => .lbracket,
            ']' => .rbracket,
            ';' => .semicolon,
            ',' => .comma,
            else => .invalid,
        };

        return Token{
            .tag = tag,
            .start = start,
            .end = self.pos,
            .line = self.line,
            .column = start_column,
        };
    }

    fn peek(self: *Tokenizer) u8 {
        if (self.pos + 1 >= self.source.len) return 0;
        return self.source[self.pos + 1];
    }
};

fn isWhitespace(c: u8) bool {
    return c == ' ' or c == '\t' or c == '\n' or c == '\r';
}

fn isDigit(c: u8) bool {
    return c >= '0' and c <= '9';
}

fn isAlpha(c: u8) bool {
    return (c >= 'a' and c <= 'z') or (c >= 'A' and c <= 'Z') or c == '_';
}

fn isIdentifierStart(c: u8) bool {
    return isAlpha(c);
}

fn isIdentifierContinue(c: u8) bool {
    return isAlpha(c) or isDigit(c);
}

fn getKeywordTag(text: []const u8) ?Token.Tag {
    return switch (std.meta.stringToEnum(Token.Tag, text ++ "_") orelse return null) {
        inline .fn_, .const_, .var_, .if_, .else_, .while_, .for_, .return_, .struct_, .enum_, .union_, .error_, .try_, .catch_, .pub_, .inline_, .comptime_, .true_, .false_, .null_, .and_, .or_, .not_ => |tag| tag,
        else => null,
    };
}

// Test
pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const source = "fn add(a: i32, b: i32) -> i32 { return a + b; }";

    var tokenizer = Tokenizer.init(source);
    var tokens = std.ArrayList(Token).init(allocator);
    defer tokens.deinit();

    while (true) {
        const token = tokenizer.nextToken();
        try tokens.append(token);
        std.debug.print("Token: {s:15} = \"{s}\"\n", .{ @tagName(token.tag), token.lexeme(source) });

        if (token.tag == .eof) break;
    }
}

