                self.column += 1;
            }

            return Token{
                .tag = .float,
                .start = start,
                .end = self.pos,
                .line = self.line,
                .column = start_column,
            };
        }

        return Token{
            .tag = .integer,
            .start = start,
            .end = self.pos,
            .line = self.line,
            .column = start_column,
        };
    }

    fn scanString(self: *Tokenizer, start: usize, start_column: usize) Token {
        self.pos += 1; // Skip opening "
        self.column += 1;

        while (self.pos < self.source.len and self.source[self.pos] != '"') {
            if (self.source[self.pos] == '\\') {
                self.pos += 2;
                self.column += 2;
            } else if (self.source[self.pos] == '\n') {
                self.line += 1;
                self.line_start = self.pos + 1;
                self.column = 1;
                self.pos += 1;
            } else {
                self.pos += 1;
                self.column += 1;
            }
        }

        if (self.pos < self.source.len) {
            self.pos += 1; // Skip closing "
            self.column += 1;
        }

        return Token{
            .tag = .string,
            .start = start,
            .end = self.pos,
            .line = self.line,
            .column = start_column,
        };
