        self.pos += 1;
        self.column += 1;

        if (self.source[self.pos] == '\\') {
            self.pos += 2;
            self.column += 2;
        } else {
            self.pos += 1;
            self.column += 1;
        }

        if (self.pos < self.source.len and self.source[self.pos] == '\'') {
            self.pos += 1;
            self.column += 1;
        }

        return Token{
            .tag = .char_literal,
            .start = start,
            .end = self.pos,
            .line = self.line,
            .column = start_column,
        };
