                    .load_string = .{
                        .index = data.index,
                        .ty = .string,
                    },
                });
            },
            .load_var => |data| {
                _ = try self.air.addInstruction(.{
                    .load_var = .{
                        .name_index = data.name_index,
                        .ty = .unknown,
                    },
                });
            },
            .store_var => |data| {
                _ = try self.air.addInstruction(.{
                    .store_var = .{
                        .name_index = data.name_index,
                        .value = data.value,
                        .ty = .unknown,
                    },
                });
            },
            .binary_op => |data| {
                // 타입 검사 수행
                const result_ty = try self.type_infer.inferBinaryOpType(data.op);
                _ = try self.air.addInstruction(.{
                    .binary_op = .{
                        .op = data.op,
                        .lhs = data.lhs,
                        .rhs = data.rhs,
                        .result_ty = result_ty,
                    },
                });
            },
            .unary_op => |data| {
                const result_ty = try self.type_infer.inferUnaryOpType(data.op);
                _ = try self.air.addInstruction(.{
                    .unary_op = .{
                        .op = data.op,
                        .operand = data.operand,
                        .result_ty = result_ty,
                    },
                });
            },
            .fn_begin => |data| {
                _ = try self.air.addInstruction(.{
                    .fn_begin = .{
                        .name_index = data.name_index,
