            .call => |data| {
                _ = try self.air.addInstruction(.{
                    .call = .{
                        .callee = data.callee,
                        .args = data.args,
                        .return_ty = .unknown,
                    },
                });
            },
            .return_val => |ret| {
                _ = try self.air.addInstruction(.{ .return_val = ret });
            },
            .cond_br => |data| {
                _ = try self.air.addInstruction(.{
                    .cond_br = .{
